        younger = 0.0
        for j in range(i + 1, m):
            younger = younger + age[j]
        midpoint = 0.5 * age[i]
        horizon = i + 1.0
        fifo_capacity = f * mu * horizon + risk * mu * cv * ((f * horizon) ** 0.5)
        lifo_share = 1.0 - f
